decision = agent.classify(ticket)
metrics.emit("confidence", decision.score)
if decision.score >= 0.90:
    execute_async(decision)
    if random.random() < 0.03:
        audit_queue.push(decision)  # Muestreo continuo
else:
    exception_queue.push(decision)  # Intervención por excepción

